ST.xhtml:p:
Rtring_Enable(CLK := g_bZCoorCutLeapFrogEnable);
IF Rtring_Enable.Q THEN
  nFrogState := 10;
   g_ZCoordCutLeapFrog.LEAPHEIGHT := g_dZCoorCutLeapHeight;
   g_ZCoordCutLeapFrog.LIFTHEIGHT := g_dZCoorCutLeapLiftHeight;
  g_bZCoorCutLeapFrogEnable := FALSE;
  g_bZCoorCutLeapDone := FALSE;
  g_bZCoorCutLeapFrogDone := FALSE;
END_IF;
g_ZCoordCutLeapFrog.REMAINTIME := g_fZLeapTime_rem;
g_ZCoordCutLeapFrog.REMAINDISTANCE := g_diMotionDistance; 


CASE nFrogState OF
  0:
	nFrogState := 0;
  10:
	g_ZCoordCutLeapFrog.EXECUTE := TRUE;
    g_ZCoordCutLeapFrog.CURHEIGHT :=g_dZCoorCutLeapSetCurHeight;
    g_ZCoordCutLeapFrog.SETHEIGHT := g_dZCoorCutLeapSetHeight;
    nFrogState := 20;
  20:
    IF g_ZCoordCutLeapFrog.LEAPDONE THEN
      g_bZCoorCutLeapDone := TRUE;
    END_IF;
    IF g_ZCoordCutLeapFrog.DONE THEN
      g_bZCoorCutLeapFrogDone := TRUE;
      nFrogState := 0;
    END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  nFrogState := 0;
  g_ZCoordCutLeapFrog.Execute := FALSE;
  g_bZCoorCutLeapFrogEnable := FALSE;
  g_bZCoorCutLeapDone := FALSE;
  g_bZCoorCutLeapFrogDone := FALSE;
END_IF;
